insert into public.processes (id, name, kind, description, status, entry_point_how) values ('b3f42fae-b5ff-5f6f-81da-b2b83badda1c', 'MIRA commons', 'Activity', 'Global knowledge graph. Called a commons to emphasize the stewardship aspect. Conflates the storage of research artifacts here.
insert into public.processes (id, name, kind, description, entry_point_how) values ('6276f7c0-127c-588a-9c24-487f062b423e', 'Priorities', 'Activity', 'Includes funder requests and PI research priorities. May include weighting of evaluation criteria.', 'Funder point of view: discover relevant research; define objectives better articulated to that research. PI point of view: discover funder requests.');
insert into public.processes (id, name, also_known_as, kind, description) values ('565851ba-f7a3-5cbd-b5d2-a042666828f0', 'Collective sensemaking', 'Sensemaking', 'Activity', 'Tooling for iterating on knowledge units: clarification, distinctions, abstraction, composition. Ideally knowledge units are superseded rather than modified. Lifecycle and governance.');
insert into public.processes (id, name, kind, description, entry_point_how) values ('333dc232-def8-5c71-84a2-21e42ca541fb', 'Plan study', 'Activity', 'Includes study selection, for now.', 'If study plans are expected to refer explicitly to target claims, requests, etc. See Priorities.');
insert into public.processes (id, name, kind, description) values ('e30fbc18-e221-513d-b338-a33690fab3fe', 'Collect', 'Activity', 'Pre-study collection.');
