insert into public.processes (id, name, kind, description, status) values ('d23cc502-5128-5590-a4b7-4dd381f3db29', 'Micro-publication', 'Activity', 'Publish from the PKG or the MIRA commons to a web view. Maybe social media references to the knowledge unit (including a link to the web view).', 'New with MIRA');
