insert into public.processes (id, name, kind, description) values ('eec7f7d5-171a-52a5-9a7d-4e21bf89c7bb', 'PKG → MIRA commons', 'Dataflow', 'Transfer from PKG to MIRA commons. Seeded from the doc; reconcile with the tldraw arrows.');
