insert into public.use_cases (id, author_name, title, level, composition_type, source) values ('d24932f5-4bb7-5a59-9654-4eedb5a0b627', 'MIRA adoption map', 'Make sense of a topic collectively', 'Goal', 'Means', 'Discussion: tool mechanisms (Semble, SciOS)');
insert into public.use_cases (id, author_name, title, level, source) values ('3fe55a48-7a81-5da0-81e5-019a57088923', 'MIRA adoption map', 'Curate a collection of links', 'Use case', 'Discussion: Semble''s mechanism');
insert into public.use_cases (id, author_name, title, level, source) values ('b8e2e3d7-1855-57fb-ac27-3b6b3293c0f4', 'MIRA adoption map', 'Discover related work and gaps in the graph', 'Use case', 'Doc: Existing tools / SciOS');
insert into public.use_cases (id, author_name, title, level, narrative, source) values ('9f706e72-550b-5fcc-b80a-24b61fc45fa9', 'MIRA adoption map', 'Post and claim research requests', 'Use case', 'Request claiming; funding.', 'Doc: Existing tools / SciOS');
insert into public.use_cases (id, author_name, title, level, composition_type, horizon, narrative, source) values ('5372ea71-8c05-515d-9cfc-b1229c489633', 'MIRA adoption map', 'Journey: MIRAfied article', 'Use case', 'Sequence', 'Aspirational', 'As an article reader, I notice that an article calls out claims and evidence explicitly, with external links. I follow one (say from a Claim) to an author-controlled local context page, where I can read more context, consult metrics, contribute a MIRA comment (and announce it), and go to a global context page connecting the claim to related claims.', 'Doc: Idealized adoption user journeys / Eg 1');
insert into public.use_cases (id, author_name, title, level, horizon, source) values ('a134e61e-d2e6-5c4c-976d-298d624112d3', 'MIRA adoption map', 'Notice explicit claims and evidence in an article', 'Step', 'Aspirational', 'Doc: Journey Eg 1');
insert into public.use_cases (id, author_name, title, level, horizon, narrative, source) values ('2f2feba5-4b3b-53bc-81a8-1a2488365025', 'MIRA adoption map', 'Follow a claim link to its local context page', 'Step', 'Aspirational', 'An author-controlled page for the claim.', 'Doc: Journey Eg 1');
insert into public.use_cases (id, author_name, title, level, horizon, narrative, source) values ('0d49dc85-5b23-5136-874a-b410484c8109', 'MIRA adoption map', 'Read the context of a claim', 'Step', 'Aspirational', 'E.g. in what conditions the author holds it to be true.', 'Doc: Journey Eg 1');
insert into public.use_cases (id, author_name, title, level, horizon, source) values ('3851f1ea-e0aa-5d91-a0fc-10ccc8c1e194', 'MIRA adoption map', 'Consult claim-specific metrics', 'Step', 'Aspirational', 'Doc: Journey Eg 1');
insert into public.use_cases (id, author_name, title, level, horizon, source) values ('57690864-88db-509e-989a-b21734d9bdc7', 'MIRA adoption map', 'Contribute a MIRA comment on a claim', 'Use case', 'Aspirational', 'Doc: Journey Eg 1, Eg 3');
insert into public.use_cases (id, author_name, title, level, horizon, narrative, virality_point, source) values ('22fd7d3c-d7d3-5262-a5d4-590277b0483d', 'MIRA adoption map', 'Announce a comment on the MIRA social knowledge graph', 'Use case', 'Aspirational', 'Links back to the original claim page, giving visibility to both the claim and the comment. "I see this as the main virality mechanism."', true, 'Doc: Journey Eg 1');
insert into public.use_cases (id, author_name, title, level, horizon, narrative, source) values ('3887776c-c7b3-55e2-a30e-0a2a40f2b952', 'MIRA adoption map', 'Explore a claim''s global context page', 'Use case', 'Aspirational', 'Connects the claim to related claims: preconditions, epistemic grounding, generalizations, competing claims. Again an opportunity for contributions.', 'Doc: Journey Eg 1, Eg 3');
insert into public.use_cases (id, author_name, title, level, composition_type, horizon, narrative, source) values ('57f0b4e8-d2fa-5101-bf9b-8184bc7e5b82', 'MIRA adoption map', 'Journey: micro-publication on social media', 'Use case', 'Sequence', 'Aspirational', 'Before an article exists, I can publish MIRA statements (or small statement graphs) on social media. Links as in the MIRAfied article journey.', 'Doc: Idealized adoption user journeys / Eg 2');
insert into public.use_cases (id, author_name, title, level, horizon, narrative, virality_point, source) values ('ac32a746-054b-553e-bc85-b131530dc8be', 'MIRA adoption map', 'Micro-publish MIRA statements on social media', 'Use case', 'Aspirational', 'Single statements or small statement graphs, before an article exists.', true, 'Doc: Journey Eg 2');
insert into public.use_cases (id, author_name, title, level, composition_type, horizon, narrative, source) values ('a880bca7-167c-5b79-afb5-bfe2639d43b6', 'MIRA adoption map', 'Journey: MIRA extractor as gateway', 'Use case', 'Sequence', 'Aspirational', 'As a reader of a conventional PDF article, I use a MIRA claim extractor to obtain a knowledge graph. Extractors remember processed articles. I get the graph plus a comment tool, human editing/validation of nodes (feedback for the AI), links to global context pages, and import into my local knowledge base.', 'Doc: Idealized adoption user journeys / Eg 3');
insert into public.use_cases (id, author_name, title, level, horizon, narrative, source) values ('e802ddf8-f454-5e80-91c4-7a40c0cce131', 'MIRA adoption map', 'Extract a knowledge graph from a PDF article', 'Use case', 'Aspirational', 'Extractors remember articles that have been processed.', 'Doc: Journey Eg 3');
insert into public.use_cases (id, author_name, title, level, horizon, narrative, source) values ('3bbdc765-820c-59b8-9c5a-9887d7f60f7f', 'MIRA adoption map', 'Edit and validate extracted nodes', 'Use case', 'Aspirational', 'Each node can be edited and validated by a human; this gives feedback for the AI.', 'Doc: Journey Eg 3');
insert into public.use_cases (id, author_name, title, level, horizon, source) values ('6e45d0a9-8ea0-553b-bd3f-02c8499a3fa1', 'MIRA adoption map', 'Request a global context page for a whole article', 'Step', 'Aspirational', 'Doc: Journey Eg 3');
insert into public.use_cases (id, author_name, title, level, horizon, narrative, source) values ('094a509b-c7ed-53c9-96eb-cee323c8d83d', 'MIRA adoption map', 'Import an extracted graph into your PKG', 'Use case', 'Aspirational', 'To think about it on my own.', 'Doc: Journey Eg 3');
